1	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
2	import { useNavigate } from "react-router";
3	import { Button } from "@/presentation/components/ui/button";
4	import type { PlayGameUseCase } from "../../application/use-cases/PlayGameUseCase";
5	import type {
6		GameCardPool,
7		GameInputMode,
8		GameItem,
9		GameRatingRecord,
10		GameRoundSummary as GameRoundSummaryData,
11	} from "../../domain/game/types";
12	import type { RecallRating } from "../../domain/shared/types";
13	import { SectionHeader } from "../components/atoms/SectionHeader";
14	import { GameHistoryList } from "../components/molecules/GameHistoryList";
15	import { GameRoundSummary } from "../components/organisms/GameRoundSummary";
16	import { SymbolDictationChallenge } from "../components/organisms/SymbolDictationChallenge";
17	import { SymbolReadingChallenge } from "../components/organisms/SymbolReadingChallenge";
18	import { WordDictationChallenge } from "../components/organisms/WordDictationChallenge";
19	import { WordProductionChallenge } from "../components/organisms/WordProductionChallenge";
20	import { useApp } from "../hooks/useApp";
21	
22	type GamePhase = "setup" | "playing" | "summary";
23	
24	/**
25	 * The setup screen's three choices, mapping to `GameCardPool` combinations
26	 * — `CardPool` values stay `"script"`/`"vocab"` everywhere below the UI
27	 * layer (see CONTEXT.md).
28	 */
29	type PoolChoice = "symbols" | "words" | "mix";
30	
31	const POOL_CHOICE_POOLS: Record<PoolChoice, readonly GameCardPool[]> = {
32		symbols: ["script"],
33		words: ["vocab"],
34		mix: ["script", "vocab"],
35	};
36	
37	const POOL_CHOICE_LABELS: Record<PoolChoice, string> = {
38		symbols: "Symbols",
39		words: "Words",
40		mix: "Mix",
41	};
42	
43	/**
44	 * The least surprising default for anyone who has only used this feature
45	 * since phase 1 — a repeat player's setup screen doesn't silently start
46	 * offering words until they choose to.
47	 */
48	const DEFAULT_POOL_CHOICE: PoolChoice = "symbols";
49	
50	const EMPTY_POOL_MESSAGES: Record<PoolChoice, string> = {
51		symbols: "No symbols to practice yet — complete a script lesson first.",
52		words: "No words to practice yet — complete a vocabulary lesson first.",
53		mix: "No items to practice yet — complete a script or vocabulary lesson first.",
54	};
55	
56	const DEFAULT_ITEM_COUNT = 10;
57	
58	/**
59	 * Selection is a pure function, so asking for every item is a side-effect-
60	 * free way to learn how many are eligible — the use case exposes no
61	 * separate count query.
62	 */
63	function countEligibleItems(
64		game: PlayGameUseCase,
65		pools: readonly GameCardPool[],
66		prioritizeWeakItems: boolean = false,
67	): number {
68		return game.startRound({
69			pools,
70			itemCount: Number.MAX_SAFE_INTEGER,
71			prioritizeWeakItems,
72			inputMode: "draw",
73		}).length;
74	}
75	
76	/**
77	 * A self-graded practice round over introduced symbols and/or vocab words,
78	 * per the setup screen's pool choice. The page owns all round state
79	 * (`items`/`ratings`/`currentIndex`) and threads it through
80	 * `PlayGameUseCase`'s pure functions — the use case is a long-lived
81	 * singleton and must never hold a round.
82	 *
83	 * Deliberately reads only `game` from `useApp()`: no `refresh()`, no
84	 * `checkAchievements`, nothing that could write the SRS blob. A practice
85	 * round must leave `thai-srs-state` byte-identical.
86	 */
87	export function GamePage() {
88		const { game } = useApp();
89		const navigate = useNavigate();
90	
91		const [phase, setPhase] = useState<GamePhase>("setup");
92		const [poolChoice, setPoolChoice] = useState<PoolChoice>(DEFAULT_POOL_CHOICE);
93		const [inputMode, setInputMode] = useState<GameInputMode>("draw");
94		const [prioritizeWeakItems, setPrioritizeWeakItems] = useState(false);
95		const [items, setItems] = useState<GameItem[]>([]);
96		const [ratings, setRatings] = useState<GameRatingRecord[]>([]);
97		const [currentIndex, setCurrentIndex] = useState(0);
98		const [summary, setSummary] = useState<GameRoundSummaryData | null>(null);
99		// Guards against a rating landing twice for one item (a stray global
100		// keypress on top of a click) advancing past the next item unseen.
101		const ratedIndexRef = useRef(-1);
102	
103		const pools = POOL_CHOICE_POOLS[poolChoice];
104	
105		const eligibleCount = useMemo(
106			() =>
107				phase === "setup"
108					? countEligibleItems(game, pools, prioritizeWeakItems)
109					: 0,
110			[game, phase, pools, prioritizeWeakItems],
111		);
112		const [countInput, setCountInput] = useState<string>(() =>
113			eligibleCount > 0
114				? String(Math.min(DEFAULT_ITEM_COUNT, eligibleCount))
115				: "",
116		);
117		// The eligible count is pool-dependent — switching pools can make a
118		// previously-typed count invalid without ever telling the learner why.
119		// biome-ignore lint/correctness/useExhaustiveDependencies: resets only when the chosen pool changes, never on every eligibleCount-affecting render
120		useEffect(() => {
121			setCountInput(
122				eligibleCount > 0
123					? String(Math.min(DEFAULT_ITEM_COUNT, eligibleCount))
124					: "",
125			);
126		}, [poolChoice]);
127		const history = useMemo(
128			() => (phase === "setup" ? game.getHistory() : null),
129			[game, phase],
130		);
131	
132		// `Number("")` is 0, which the >= 1 rule already rejects.
133		const parsedCount = Number(countInput);
134		const countValid =
135			Number.isInteger(parsedCount) &&
136			parsedCount >= 1 &&
137			parsedCount <= eligibleCount;
138	
139		const handleStart = useCallback(() => {
140			const roundItems = game.startRound({
141				pools,
142				itemCount: parsedCount,
143				prioritizeWeakItems,
144				inputMode,
145			});
146			if (roundItems.length === 0) return;
147			setItems(roundItems);
148			setRatings([]);
149			setCurrentIndex(0);
150			setSummary(null);
151			ratedIndexRef.current = -1;
152			setPhase("playing");
153		}, [game, pools, parsedCount, inputMode, prioritizeWeakItems]);
154	
155		const handleRate = useCallback(
156			(rating: RecallRating) => {
157				if (ratedIndexRef.current >= currentIndex) return;
158				ratedIndexRef.current = currentIndex;
159	
160				const nextRatings = game.recordRating(
161					items,
162					ratings,
163					currentIndex,
164					rating,
165				);
166				setRatings(nextRatings);
167	
168				if (currentIndex + 1 < items.length) {
169					setCurrentIndex(currentIndex + 1);
170					return;
171				}
172	
173				const roundSummary = game.finishRound(nextRatings);
174				game.saveHistory({ pools, itemCount: items.length }, roundSummary);
175				setSummary(roundSummary);
176				setPhase("summary");
177			},
178			[game, items, ratings, currentIndex, pools],
179		);
180	
181		if (phase === "playing") {
182			const item = items[currentIndex];
183			if (!item) return null;
184	
185			// The page dispatches by `kind` then `challengeDirection`; each
186			// organism receives a single-kind, single-direction prop and never
187			// inspects `GameItem`'s union tag itself (see task 2.3's
188			// architectural decision).
189			const challenge =
190				item.kind === "symbol" ? (
191					item.challengeDirection === "dictation" ? (
192						<SymbolDictationChallenge
193							item={item}
194							inputMode={inputMode}
195							onRate={handleRate}
196						/>
197					) : (
198						<SymbolReadingChallenge item={item} onRate={handleRate} />
199					)
200				) : item.challengeDirection === "dictationTranslate" ? (
201					<WordDictationChallenge
202						item={item}
203						inputMode={inputMode}
204						onRate={handleRate}
205					/>
206				) : (
207					<WordProductionChallenge
208						item={item}
209						inputMode={inputMode}
210						onRate={handleRate}
211					/>
212				);
213	
214			return (
215				<div>
216					<div className="mb-4 flex items-center justify-between">
217						<span
218							className="text-sm font-semibold"
219							style={{ color: "var(--color-text)" }}
220						>
221							Practice Round
222						</span>
223						<span
224							className="text-sm"
225							style={{ color: "var(--color-text-muted)" }}
226						>
227							{currentIndex + 1} / {items.length}
228						</span>
229						<button
230							type="button"
231							onClick={() => navigate("/")}
232							className="text-lg leading-none"
233							style={{ color: "var(--color-text-muted)" }}
234							aria-label="End round"
235							title="End round"
236						>
237							✕
238						</button>
239					</div>
240	
241					{challenge}
242				</div>
243			);
244		}
245	
246		if (phase === "summary" && summary) {
247			return (
248				<div className="space-y-6 py-8">
249					<GameRoundSummary summary={summary} itemCount={items.length} />
250					<div className="space-y-3">
251						<Button className="w-full" onClick={() => setPhase("setup")}>
252							Play Again
253						</Button>
254						<Button
255							variant="outline"
256							className="w-full"
257							onClick={() => navigate("/")}
258						>
259							Go to Dashboard
260						</Button>
261					</div>
262				</div>
263			);
264		}
265	
266		return (
267			<div className="space-y-6 py-4">
268				<div>
269					<h1
270						className="text-2xl font-semibold"
271						style={{ color: "var(--color-text)" }}
272					>
273						Practice Game
274					</h1>
275					<p
276						className="text-sm mt-1"
277						style={{ color: "var(--color-text-muted)" }}
278					>
279						Self-graded drilling over your introduced symbols and words — it never
280						changes your review schedule.
281					</p>
282				</div>
283	
284				<fieldset
285					className="rounded-xl p-4"
286					style={{
287						border: "1px solid var(--color-border)",
288						background: "var(--color-surface)",
289					}}
290				>
291					<legend
292						className="text-sm font-semibold mb-1"
293						style={{ color: "var(--color-text)" }}
294					>
295						Practice pool
296					</legend>
297					<div className="flex gap-4">
298						{(Object.keys(POOL_CHOICE_POOLS) as PoolChoice[]).map((choice) => (
299							<span key={choice} className="flex items-center gap-2">
300								<input
301									id={`game-pool-${choice}`}
302									type="radio"
303									name="game-pool-choice"
304									checked={poolChoice === choice}
305									onChange={() => setPoolChoice(choice)}
306								/>
307								<label
308									htmlFor={`game-pool-${choice}`}
309									className="text-sm"
310									style={{ color: "var(--color-text)" }}
311								>
312									{POOL_CHOICE_LABELS[choice]}
313								</label>
314							</span>
315						))}
316					</div>
317				</fieldset>
318	
319				{eligibleCount === 0 ? (
320					<p
321						className="rounded-xl p-4 text-sm"
322						style={{
323							background: "var(--color-surface-2)",
324							color: "var(--color-text-muted)",
325						}}
326					>
327						{EMPTY_POOL_MESSAGES[poolChoice]}
328					</p>
329				) : (
330					<div
331						className="rounded-xl p-4 space-y-4"
332						style={{
333							border: "1px solid var(--color-border)",
334							background: "var(--color-surface)",
335						}}
336					>
337						<div>
338							<label
339								htmlFor="game-item-count"
340								className="block text-sm font-semibold mb-1"
341								style={{ color: "var(--color-text)" }}
342							>
343								Items per round
344							</label>
345							<input
346								id="game-item-count"
347								type="number"
348								min={1}
349								max={eligibleCount}
350								step={1}
351								value={countInput}
352								onChange={(e) => setCountInput(e.target.value)}
353								className="w-full rounded-xl p-3"
354								style={{
355									border: "1px solid var(--color-border)",
356									background: "var(--color-surface-2)",
357									color: "var(--color-text)",
358								}}
359							/>
360							<p
361								className="text-xs mt-1"
362								style={{ color: "var(--color-text-muted)" }}
363							>
364								Whole number from 1 to {eligibleCount}
365							</p>
366						</div>
367	
368						<fieldset>
369							<legend
370								className="text-sm font-semibold mb-1"
371								style={{ color: "var(--color-text)" }}
372							>
373								Input mode
374							</legend>
375							<div className="flex gap-4">
376								<span className="flex items-center gap-2">
377									<input
378										id="game-input-draw"
379										type="radio"
380										name="game-input-mode"
381										checked={inputMode === "draw"}
382										onChange={() => setInputMode("draw")}
383									/>
384									<label
385										htmlFor="game-input-draw"
386										className="text-sm"
387										style={{ color: "var(--color-text)" }}
388									>
389										Draw on canvas
390									</label>
391								</span>
392								<span className="flex items-center gap-2">
393									<input
394										id="game-input-paper"
395										type="radio"
396										name="game-input-mode"
397										checked={inputMode === "paper"}
398										onChange={() => setInputMode("paper")}
399									/>
400									<label
401										htmlFor="game-input-paper"
402										className="text-sm"
403										style={{ color: "var(--color-text)" }}
404									>
405										Write on paper
406									</label>
407								</span>
408							</div>
409						</fieldset>
410	
411						<div className="flex items-center gap-2">
412							<input
413								id="game-prioritize-weak"
414								type="checkbox"
415								checked={prioritizeWeakItems}
416								onChange={(e) => setPrioritizeWeakItems(e.target.checked)}
417							/>
418							<label
419								htmlFor="game-prioritize-weak"
420								className="text-sm"
421								style={{ color: "var(--color-text)" }}
422							>
423								Prioritize weak items
424							</label>
425						</div>
426	
427						<Button
