62	
63	/** A raw `PropertyCard` DTO as it sits inside the persisted SRS blob. */
64	function scriptCardDTO(character: string) {
65		return {
66			id: `${character}-recognition`,
67			question: `What sound does ${character} make?`,
68			correctAnswer: "answer",
69			choices: ["answer", "other"],
70			srs: {
71				easeFactor: 2,
72				interval: 10,
73				repetitions: 0,
74				learningStep: 1,
75				nextReviewDate: "2026-01-01T00:00:00.000Z",
76				lastReviewDate: null,
77				lapseCount: 0,
78			},
79			symbolCharacter: character,
80			property: "recognition",
81			lessonNumber: 1,
82		};
83	}
84	
85	/** A raw `VocabCard` DTO as it sits inside the persisted SRS blob. */
86	function vocabCardDTO(thai: string, property = "thaiToEnglish") {
87		return {
88			id: `vocab:${thai}:${property}`,
89			question: `What does ${thai} mean?`,
90			correctAnswer: "answer",
91			choices: ["answer", "other"],
92			srs: {
93				easeFactor: 2,
94				interval: 10,
95				repetitions: 0,
96				learningStep: 1,
97				nextReviewDate: "2026-01-01T00:00:00.000Z",
98				lastReviewDate: null,
99				lapseCount: 0,
100			},
101			promptWord: thai,
102			property,
103		};
104	}
105	
106	/** A `WordGameItem` with a pre-assigned direction, for fixed-round tests. */
107	function makeWordItem(
108		thaiWord: string,
109		challengeDirection: WordChallengeDirection,
110		overrides: Partial<Omit<WordItemContent, "kind">> = {},
111	): GameItem {
112		return {
113			kind: "word",
114			thaiWord,
115			englishMeaning: `${thaiWord} meaning`,
116			audioUrl: `/audio/${thaiWord}.mp3`,
117			...overrides,
118			challengeDirection,
119		};
120	}
121	
122	/** An in-memory `VocabCard`, for a `WordGameItemSource`'s eligibility. */
123	function vocabCard(thai: string, property = "thaiToEnglish"): VocabCard {
124		return new VocabCard(
125			`vocab:${thai}:${property}`,
126			"question",
127			"answer",
128			["answer"],
129			SrsSchedule.initial(),
130			thai,
131			property,
132		);
133	}
134	
135	/**
136	 * A real `PlayGameUseCase` wired over both pools — `makeGame` in
137	 * `renderWithApp.tsx` only registers `SymbolGameItemSource` (phase 1's
138	 * seam), so a real Words/Mix round needs its own selection service here.
139	 */
140	function makeMixGame(
141		symbolChars: readonly string[],
142		vocabThaiWords: readonly string[],
143	): { game: PlayGameUseCase } {
144		const cardRepo = new StorageCardRepository(new InMemoryStorage());
145		cardRepo.saveAll(symbolChars.map(makeScriptCard));
146		cardRepo.saveAll(vocabThaiWords.map((thai) => vocabCard(thai)));
147		const game = new PlayGameUseCase(
148			new GameItemSelectionService([
149				new SymbolGameItemSource(cardRepo),
150				new WordGameItemSource(cardRepo, vocabularyData as VocabEntry[]),
151			]),
152			new StorageGameHistoryRepository(
153				new InMemoryJsonStore<GameHistoryEntry[]>(),
154			),
155		);
156		return { game };
157	}
