231			renderWithApp(<GamePage />, { game });
232			startRound();
233	
234			expect(screen.getByText("1 / 2")).toBeTruthy();
235			expect(screen.queryByRole("button", { name: /Again/ })).toBeNull();
236			reveal();
237			expect(screen.getByRole("button", { name: /Again/ })).toBeTruthy();
