249		it("leaves the whole thai-srs-state blob byte-identical after a full round through the real AppProvider", () => {
250			const seeded = JSON.stringify({
251				completedLessons: [1],
252				currentLesson: 2,
253				cards: {
254					"ม-recognition": scriptCardDTO("ม"),
255					"น-recognition": scriptCardDTO("น"),
256					"ง-recognition": scriptCardDTO("ง"),
257				},
258				vocabCards: {},
259				grammarCards: {},
260				sentenceCards: {},
261				// Streak/achievement material lives in these fields — the whole
262				// blob must survive, not just card schedules.
263				sessionHistory: [
264					{
265						sessionId: "s-1",
266						completedAt: "2026-09-01T10:00:00.000Z",
267						type: "review",
268						durationMs: 60000,
269						totalCards: 5,
270						correctCount: 4,
271						incorrectCount: 1,
272						accuracy: 80,
273						newCardsGraduated: 1,
274					},
275				],
276				achievements: ["first-lesson"],
277			});
278			getFakeLocalStorage().setItem("thai-srs-state", seeded);
279	
280			render(
281				<AppProvider>
282					<MemoryRouter initialEntries={["/game"]}>
283						<Routes>
284							<Route path="/game" element={<GamePage />} />
285						</Routes>
286					</MemoryRouter>
287				</AppProvider>,
