341			expect(screen.getByText(/No symbols to practice yet/)).toBeTruthy();
342			expect(screen.queryByRole("button", { name: "Start Round" })).toBeNull();
343		});
344	
345		// AC7 — two consecutive same-direction items keep the same component
346		// instance (same element type, same position, no key), so React's default
347		// reconciliation does not remount: the organism's own id-keyed effect
348		// must do the resetting.
349		it("resets reveal and canvas across two consecutive dictation items", () => {
350			const first = makeSymbolItem("ม", "dictation", {
351				audioUrl: "/audio/first.mp3",
352			});
353			const second = makeSymbolItem("น", "dictation", {
354				audioUrl: "/audio/second.mp3",
355			});
356			const { game } = makeFixedRoundGame([first, second]);
357			renderWithApp(<GamePage />, { game });
358			startRound();
359	
360			reveal();
361			expect(screen.getByRole("button", { name: /Again/ })).toBeTruthy();
362			canvas2d.clearRect.mockClear();
363			rate(/Good/);
364	
365			// Second dictation item: unrevealed again, canvas cleared, and the
366			// id-keyed effect re-ran (its prompt audio was constructed).
367			expect(screen.getByRole("button", { name: "Show Answer" })).toBeTruthy();
368			expect(screen.queryByRole("button", { name: /Again/ })).toBeNull();
369			expect(canvas2d.clearRect).toHaveBeenCalled();
370			expect(createdAudioUrls()).toContain("/audio/second.mp3");
371		});
372	
373		// AC7
374		it("resets reveal across two consecutive reading items", () => {
375			const { game } = makeFixedRoundGame([
376				makeSymbolItem("ม", "reading"),
377				makeSymbolItem("น", "reading"),
378			]);
379			renderWithApp(<GamePage />, { game });
380			startRound();
381	
382			reveal();
383			expect(screen.getByRole("button", { name: /Again/ })).toBeTruthy();
384			rate(/Good/);
385	
386			expect(screen.getByRole("button", { name: "Show Answer" })).toBeTruthy();
387			expect(screen.queryByRole("button", { name: /Again/ })).toBeNull();
388		});
389	
390		// AC8
391		it("keeps start unavailable for zero, negative, and non-integer item counts", () => {
392			renderWithApp(<GamePage />, {}, { symbols: ["ม", "น", "ง"] });
393			const start = screen.getByRole("button", {
394				name: "Start Round",
395			}) as HTMLButtonElement;
396	
397			for (const bad of ["0", "-2", "2.5", "", "99"]) {
398				setCount(bad);
399				expect(start.disabled).toBe(true);
400			}
401	
402			setCount("2");
403			expect(start.disabled).toBe(false);
404		});
405	
406		// AC9 — jsdom's default (no md: desktop viewport) is exactly the mobile
407		// case: the Dashboard card must be reachable without the desktop nav.
408		it("dashboard shows a game quick-action card that navigates to /game", () => {
409			renderWithApp(
410				<Routes>
411					<Route path="/" element={<Dashboard />} />
412					<Route path="/game" element={<GamePage />} />
413				</Routes>,
414			);
415	
416			expect(screen.getByText("Game")).toBeTruthy();
417			fireEvent.click(screen.getByText("Practice round"));
418			expect(screen.getByText("Practice Game")).toBeTruthy();
419		});
420	
421		// AC10
422		it("abandoning a round persists nothing and the next round starts clean", () => {
423			const { game, historyStore } = makeFixedRoundGame([
424				makeSymbolItem("ม", "reading"),
425				makeSymbolItem("น", "reading"),
426			]);
427			renderWithApp(
428				<Routes>
429					<Route
430						path="/"
431						element={
432							<div>
433								Dashboard home
434								<Link to="/game">back to game</Link>
435							</div>
436						}
437					/>
438					<Route path="/game" element={<GamePage />} />
439				</Routes>,
440				{ game },
441				{ route: "/game" },
442			);
443	
444			// Start (default count 2), rate one item, abandon mid-round.
445			startRound();
446			reveal();
447			rate(/Again/);
448			fireEvent.click(screen.getByRole("button", { name: "End round" }));
449			expect(screen.getByText("Dashboard home")).toBeTruthy();
450			expect(historyStore.load()).toEqual({ status: "empty" });
451	
452			// Returning shows setup, with no history entry from the abandoned round.
453			fireEvent.click(screen.getByText("back to game"));
454			expect(screen.getByText("Practice Game")).toBeTruthy();
455			expect(screen.getByText("No games played yet.")).toBeTruthy();
456	
457			// A fresh round tallies only its own ratings.
458			startRound();
459			reveal();
460			rate(/Good/);
461			reveal();
462			rate(/Good/);
463			expect(screen.getByText("2 of 2 items rated")).toBeTruthy();
464			expect(screen.getByText("100%")).toBeTruthy();
465			expect(screen.getByText("Again").parentElement?.textContent).toBe("0Again");
466	
467			const persisted = historyStore.load();
468			expect(persisted.status).toBe("ok");
469			if (persisted.status === "ok") {
470				expect(persisted.value).toHaveLength(1);
471			}
472		});
