330	// --- The harness itself ---
331	
332	export interface AppHarness {
333		value: AppContextValue;
334		storage: InMemoryStorage;
335		cardRepo: StorageCardRepository;
336		historyStore: InMemoryJsonStore<GameHistoryEntry[]>;
337		game: PlayGameUseCase;
338	}
339	
340	export interface MakeAppValueOptions {
341		/** Characters (existing in `symbols.ts`) to seed one script card each for. */
342		symbols?: readonly string[];
343	}
344	
345	/**
346	 * A complete in-memory `AppContextValue`: every use case and service the
347	 * real `AppContext.tsx` wires, built over `InMemoryStorage` instead of
348	 * `localStorage`, plus a real `PlayGameUseCase` over an in-memory history
349	 * store. `refresh` and `checkAchievements` are inert stubs — pass overrides
350	 * if a test needs either to be observable.
351	 */
352	export function makeAppValue(options: MakeAppValueOptions = {}): AppHarness {
353		const storage = new InMemoryStorage();
354		const cardRepo = new StorageCardRepository(storage);
355		const stateRepo = new StorageLearnerStateRepository(storage);
356		const apprenticeService = new ApprenticeService(cardRepo);
357		const leechService = new LeechService(cardRepo);
358		const learningService = new LearningService(
359			cardRepo,
360			stateRepo,
361			apprenticeService,
362		);
363		const reviewService = new ReviewService(cardRepo, stateRepo);
364		const vocabularyService = new VocabularyService(
365			cardRepo,
366			stateRepo,
367			vocabularyData as VocabEntry[],
368		);
369		const grammarService = new GrammarService(
370			cardRepo,
371			grammarData as unknown as GrammarEntry[],
372			apprenticeService,
373			vocabularyData as VocabEntry[],
374		);
375		const sentenceService = new SentenceService(
376			cardRepo,
377			sentenceData as unknown as SentenceEntry[],
378			vocabularyService,
379			apprenticeService,
380		);
381	
382		cardRepo.saveAll((options.symbols ?? []).map(makeScriptCard));
383	
384		const historyStore = new InMemoryJsonStore<GameHistoryEntry[]>();
385		const game = new PlayGameUseCase(
386			new GameItemSelectionService([new SymbolGameItemSource(cardRepo)]),
387			new StorageGameHistoryRepository(historyStore),
388		);
389	
390		const value: AppContextValue = {
391			state: storage.load(),
392			refresh: () => {},
393			lesson: new StartLessonUseCase(
394				learningService,
395				vocabularyService,
396				grammarService,
397				sentenceService,
398			),
399			review: new ConductReviewUseCase(
400				reviewService,
401				new NotificationScheduler(),
402			),
403			dashboard: new QueryDashboardUseCase(
404				cardRepo,
405				apprenticeService,
406				leechService,
407			),
408			data: new ManageDataUseCase(stateRepo),
409			items: new ManageItemsUseCase(cardRepo),
410			vocab: vocabularyService,
411			checkAchievements: () => [],
412			game,
413		};
414	
415		return { value, storage, cardRepo, historyStore, game };
416	}
417	
418	export interface RenderWithAppOptions extends MakeAppValueOptions {
419		/** Initial router entry, default `/`. */
420		route?: string;
421	}
422	
423	/**
424	 * Renders `ui` inside `<AppContext.Provider>` (a fresh in-memory
425	 * `AppContextValue`, with `overrides` merged in) and a `MemoryRouter`.
426	 * Returns Testing-Library's render result plus the harness internals.
427	 */
428	export function renderWithApp(
429		ui: ReactElement,
430		overrides: Partial<AppContextValue> = {},
431		options: RenderWithAppOptions = {},
432	): RenderResult & { app: AppHarness } {
433		const app = makeAppValue({ symbols: options.symbols });
434		const value: AppContextValue = { ...app.value, ...overrides };
435		const result = render(
436			<AppContext.Provider value={value}>
437				<MemoryRouter initialEntries={[options.route ?? "/"]}>{ui}</MemoryRouter>
438			</AppContext.Provider>,
439		);
440		return Object.assign(result, { app: { ...app, value, game: value.game } });
441	}
