4	} from "../../domain/game/ports/GameHistoryRepository";
5	import type { GameCardPool, GameHistoryEntry } from "../../domain/game/types";
6	import type { JsonShapeGuard, JsonStore } from "./JsonStore";
7	
8	/**
9	 * Deliberately its own key, never a field on `thai-srs-state`: game history
10	 * is a practice log, not SRS progress, so it must survive an SRS reset and
11	 * stay untouched by `ManageDataUseCase.exportData()`. See CONTEXT.md.
12	 */
13	export const GAME_HISTORY_STORAGE_KEY = "thai-srs-game-history";
14	
15	/**
16	 * The allowlist this file's shape guard checks a persisted `pools` entry
17	 * against, derived from `GameCardPool` rather than hand-maintained beside
18	 * it. A `Record<GameCardPool, true>` must name every member, so adding a
19	 * pool to `GameCardPool` is a compile error *here* — which is the whole
20	 * point.
21	 *
22	 * A hand-written `readonly GameCardPool[]` (what this was) type-checks
23	 * happily while missing members, and a missing member is not a cosmetic
24	 * gap: `isGameHistoryEntry` failing one entry makes `isGameHistoryEntryArray`
25	 * reject the *entire* stored array, `list()` report `unavailable`, and the
26	 * next `save()` overwrite the learner's whole game history with the single
27	 * new entry. That is exactly what the first `pools: ["sentence"]` round
28	 * would have done.
29	 */
30	const GAME_CARD_POOL_ALLOWLIST: Record<GameCardPool, true> = {
31		script: true,
32		vocab: true,
33		sentence: true,
34	};
35	
36	const GAME_CARD_POOLS: ReadonlySet<string> = new Set(
37		Object.keys(GAME_CARD_POOL_ALLOWLIST),
38	);
39	
40	function isGameCardPool(value: unknown): value is GameCardPool {
41		return typeof value === "string" && GAME_CARD_POOLS.has(value);
42	}
43	
44	/**
45	 * Shallow shape check for one persisted `GameHistoryEntry.summary` — enough
46	 * to reject a corrupt or foreign blob, matching `Validation.ts`'s own
47	 * shallow-not-exhaustive style for the SRS blob.
48	 */
49	function hasGameRoundSummaryShape(value: unknown): boolean {
50		if (value === null || typeof value !== "object") return false;
51		const summary = value as Record<string, unknown>;
52	
53		if (
54			typeof summary.ratingCounts !== "object" ||
55			summary.ratingCounts === null
56		) {
57			return false;
58		}
59		if (typeof summary.ratedCount !== "number") return false;
60		return summary.accuracy === null || typeof summary.accuracy === "number";
61	}
62	
63	/**
64	 * Shallow shape check for one persisted `GameHistoryEntry` — enough to
65	 * reject a corrupt or foreign blob, not a full domain-validity check.
66	 */
67	function isGameHistoryEntry(value: unknown): value is GameHistoryEntry {
68		if (value === null || typeof value !== "object") return false;
69		const entry = value as Record<string, unknown>;
70	
71		return (
72			typeof entry.id === "string" &&
73			typeof entry.playedAt === "string" &&
74			typeof entry.itemCount === "number" &&
75			Array.isArray(entry.pools) &&
76			entry.pools.every(isGameCardPool) &&
77			hasGameRoundSummaryShape(entry.summary)
78		);
79	}
80	
81	/** Shape guard for the `JsonStore<GameHistoryEntry[]>` this repository is built over. */
82	export const isGameHistoryEntryArray: JsonShapeGuard<GameHistoryEntry[]> = (
83		value,
84	): value is GameHistoryEntry[] =>
85		Array.isArray(value) && value.every(isGameHistoryEntry);
86	
87	/**
88	 * `GameHistoryRepository` over a `JsonStore<GameHistoryEntry[]>` — a
89	 * corrupt store maps to `{status:"unavailable"}`, an empty one to
90	 * `{status:"ok", entries:[]}`, and listing sorts most-recent-first.
91	 */
92	export class StorageGameHistoryRepository implements GameHistoryRepository {
93		constructor(private readonly store: JsonStore<GameHistoryEntry[]>) {}
94	
95		list(): GameHistoryListResult {
96			const result = this.store.load();
97			if (result.status === "corrupt") return { status: "unavailable" };
98			if (result.status === "empty") return { status: "ok", entries: [] };
99			return {
100				status: "ok",
101				entries: [...result.value].sort((a, b) =>
102					b.playedAt.localeCompare(a.playedAt),
103				),
104			};
105		}
106	
107		save(entry: GameHistoryEntry): void {
108			const current = this.list();
109			const entries = current.status === "ok" ? current.entries : [];
110			this.store.save([...entries, entry]);
111		}
112	}
